from collections import OrderedDict


class LRUCache:
    """LRU cache with a fixed maximum capacity.

    ``get(key)`` returns the stored value or ``None`` and marks the key as
    recently used.  ``put(key, value)`` inserts or updates a key (also marking
    it as recently used); if inserting a new key would exceed the capacity,
    the least recently used key is evicted first.  ``len(cache)`` returns the
    number of stored keys.
    """

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data[key] = value
            self._data.move_to_end(key)
            return
        if len(self._data) >= self.capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data

    def __repr__(self):
        return "LRUCache(capacity=%r, data=%r)" % (self.capacity, list(self._data.items()))
